import pandas as pd

def clean(df):
    df = df.drop_duplicates().reset_index(drop=True)
    df['Category'] = df['Category'].replace('office supplies', 'Office Supplies')
    return df

def answer(df):
    df = clean(df)
    counts = df.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
